typedef float rational_t;
typedef unsigned long uint64;

class pstring
{
private:
  uint64 pchunk[4];
  void pack_string(const char *the_string);

public:
  pstring(const char *target_string)
  {
    pack_string(target_string);
  }

  bool operator==(const pstring &check_me) const
  {
    for (unsigned i = 0; i < 4; ++i)
    {
      if (pchunk[i] != check_me.pchunk[i])
        return false;
    }
    return true;
  }
};

class generic_interface
{
public:
  virtual ~generic_interface();
  virtual bool get_ifc_num(const pstring &, rational_t &);
  virtual bool set_ifc_num(const pstring &, rational_t);
};

class entity_interface : public generic_interface
{
protected:
  void *my_entity;
};

typedef enum
{
  _TIME_WORLD = 0,
  _TIME_ABSOLUTE = 1,
  _TIME_RELATIVE = 2
} eTimeMode;

class time_interface : public entity_interface
{
protected:
  rational_t time_dilation;
  eTimeMode time_mode;

public:
  void set_mode(eTimeMode mode) { time_mode = mode; }
  virtual bool set_ifc_num(const pstring &att, rational_t val);
};

#define IFC_INTERNAL_SET_MACRO(a,b) { static pstring pstring_set(a); if(att == pstring_set) { b = val; return(true); } }

bool time_interface::set_ifc_num(const pstring &att, rational_t val)
{
  IFC_INTERNAL_SET_MACRO("TIME_DILATION", time_dilation);

  static pstring check_mode("TIME_MODE");
  if(att == check_mode)
  {
    set_mode((eTimeMode)((int)val));
    return(true);
  }



  return(false);
}
